{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Risperidone has a measured absolute oral bioavailability of 70% in humans; with the highest transfer score, this directly supports F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Bitopertin shows high absolute bioavailability in healthy volunteers; its sulfonamide and heteroaromatic features are relevant to the query and support high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Brexpiprazole has 95% absolute oral bioavailability in healthy subjects, demonstrating that a lipophilic, basic amine-containing drug can have excellent oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Daridorexant has 62% absolute oral bioavailability in healthy subjects, supporting high F for a moderately lipophilic, high-molecular-weight drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Nilotinib, the closest structural analogue, has a measured absolute oral bioavailability of 31% under fasted conditions, above the 20% threshold; this is the most direct structural evidence for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A simulation predicted nilotinib bioavailability of 16% at a 400 mg dose, suggesting solubility-limited absorption could lower F; however, this is model-based and contradicted by the measured 31% absolute F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer human absolute-bioavailability evidence (risperidone 70%, bitopertin high, brexpiprazole 95%, daridorexant 62%, nilotinib 31%) supports F ≥ 20%. The closest structural analogue nilotinib has a measured F of 31%, above threshold, despite some model-based lower estimates. Therefore predict high.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the query molecule.",
    "Nilotinib low-F estimates are model-based or predicted, not direct measured values.",
    "Solubility-limited absorption and first-pass metabolism of the query are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

